from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png')).astype(float)
# measure ball exact colors in spherical normalized coordinates
cx,cy,r=81.8,57.2,10.8
for yy in range(46,70):
 row=[]
 for xx in range(70,94):
  if ((xx-cx)/r)**2+((yy-cy)/r)**2<1:
   p=im[yy,xx]; row.append(int(p[2]-p[0]))
  else: row.append(-999)
 # print quantized map
 if any(v>-900 for v in row): print(yy, ''.join(' ' if v==-999 else ' .:-=+*#%@'[min(9,max(0,int(v/15)))] for v in row))
PY"

